piezas.js:
(() => {
  const chart = document.getElementById("mjGsdChart");
  const datos = [4,7,5,9,12,8,3,6,10,14,11,9,5,7].map((p, i) => ({ etiqueta: `${i + 1} de noviembre`, personas: p, vistas: p * 3 }));
  function pintar() {
    const W = chart.clientWidth || 600, H = 240, izq = 34, abajo = 22, arriba = 8;
    const max = Math.max(...datos.map(d => d.personas), 1), paso = Math.max(1, Math.ceil(max / 4)), tope = Math.ceil(max / paso) * paso;
    const ancho = (W - izq) / datos.length, gap = Math.min(2, ancho * .2), alto = H - abajo - arriba, y = v => arriba + alto - alto * v / tope;
    let svg = "";
    for (let v = 0; v <= tope; v += paso) svg += `<line class="${v ? "linea" : "base"}" x1="${izq}" x2="${W}" y1="${y(v)}" y2="${y(v)}"/><text class="eje" x="${izq - 8}" y="${y(v) + 4}" text-anchor="end">${v}</text>`;
    const cada = Math.ceil(datos.length / Math.max(2, Math.floor(W / 110)));
    datos.forEach((d, i) => {
      const x = izq + i * ancho, h = alto * d.personas / tope, bw = Math.max(1, ancho - gap), r = Math.min(4, bw / 2, h);
      svg += `<rect class="hit" data-i="${i}" x="${x}" y="${arriba}" width="${ancho}" height="${alto}"/>`;
      svg += `<path class="barra" d="M${x},${y(0)} V${y(d.personas) + r} q0,-${r} ${r},-${r} h${bw - 2 * r} q${r},0 ${r},${r} V${y(0)} Z"/>`;
      if (i % cada === 0) svg += `<text class="eje" x="${x + ancho / 2}" y="${H - 4}" text-anchor="middle">${i + 1} nov</text>`;
    });
    chart.innerHTML = `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${svg}</svg><div class="tip"></div>`;
    const tip = chart.querySelector(".tip"), s = chart.querySelector("svg"); let marcada;
    s.addEventListener("mousemove", e => { const hit = e.target.closest(".hit"); if (!hit) return; const x = datos[+hit.dataset.i];
      marcada?.classList.remove("on"); marcada = hit.nextElementSibling; marcada.classList.add("on");
      tip.innerHTML = `${x.etiqueta}<br><b>${x.personas}</b> personas · ${x.vistas} páginas vistas`;
      const c = chart.getBoundingClientRect(), hr = hit.getBoundingClientRect();
      tip.style.left = Math.min(Math.max(hr.left + hr.width / 2 - c.left, 90), c.width - 90) + "px"; tip.style.top = "4px"; tip.classList.add("on"); });
    s.addEventListener("mouseleave", () => { tip.classList.remove("on"); marcada?.classList.remove("on"); });
  }
  pintar(); let t; addEventListener("resize", () => { clearTimeout(t); t = setTimeout(pintar, 120); });
})();

