.mj-tabla-listado tbody tr:hover td { background: #fafaf5; }
.mj-tabla-listado .num { font-weight: 800; }
.mj-tabla-listado .muted { color: var(--muted); }
.mj-tabla-listado .r { text-align: right; white-space: nowrap; }
