.mj-tabla-listado .pill.pagada { background: #e6f3ea; color: #2f7d4f; }
.mj-tabla-listado .pill.borrador { background: #eeede5; color: var(--muted); }
.mj-tabla-listado .del { border: 0; background: none; cursor: pointer; font-size: 14px; opacity: .35; padding: 2px 6px; border-radius: 6px; }
.mj-tabla-listado .del:hover { opacity: 1; background: #fbe4e4; }

piezas.js:
document.querySelectorAll(".mj-tabla-listado").forEach(t => {
  t.querySelector(".tabs").onclick = e => { const b = e.target.closest("button"); if (b) t.querySelectorAll(".tabs button").forEach(x => x.classList.toggle("on", x === b)); };
  t.querySelector(".search").oninput = e => { const q = e.target.value.toLowerCase(); t.querySelectorAll("tbody tr").forEach(tr => tr.hidden = !tr.textContent.toLowerCase().includes(q)); };
  t.querySelectorAll("button.pill").forEach(p => p.onclick = e => { e.stopPropagation(); const pag = p.classList.contains("pagada"); p.className = "pill " + (pag ? "pendiente" : "pagada"); p.textContent = pag ? "pendiente" : "pagada"; });
});

