document.querySelectorAll(".mj-calendario-tareas").forEach(c => {
  const tip = c.querySelector(".tip");
  c.addEventListener("mouseover", e => { const ev = e.target.closest(".ev"); if (!ev) return;
    const [k, t, m] = ev.dataset.tip.split("|"), cs = getComputedStyle(ev);
    tip.innerHTML = `<div class="k" style="--c-bar:${cs.getPropertyValue("--c-bar")}"><i></i>${k}</div><b>${t}</b><div class="m">${m}</div>`;
    const b = ev.getBoundingClientRect(), alto = tip.offsetHeight;
    tip.style.left = Math.max(8, Math.min(innerWidth - 278, b.left)) + "px";
    tip.style.top = (b.bottom + alto + 12 > innerHeight ? b.top - alto - 6 : b.bottom + 6) + "px"; tip.classList.add("on"); });
  c.addEventListener("mouseout", e => { if (e.target.closest(".ev") && !e.relatedTarget?.closest?.(".ev")) tip.classList.remove("on"); });
  addEventListener("scroll", () => tip.classList.remove("on"), { passive: true });
  c.querySelector(".filtro").onclick = e => { const b = e.target.closest("button"); if (b) c.querySelectorAll(".filtro button").forEach(x => x.classList.toggle("on", x === b)); };
});

