function mjDialogo({ titulo, texto, ok = "Aceptar", cancelar, peligro }) {
  return new Promise(resolve => {
    const d = document.createElement("dialog"), e = s => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;");
    d.className = "mj-dialogo-confirmacion-dlg" + (peligro ? " peligro" : "");
    d.innerHTML = `<div class="mj-dialogo-confirmacion-ic">${peligro ? "!" : "i"}</div><div class="mj-dialogo-confirmacion-txt">${titulo ? `<b>${e(titulo)}</b>` : ""}<p>${e(texto)}</p></div>
      <div class="mj-dialogo-confirmacion-acts">${cancelar ? `<button type="button" class="mj-dialogo-confirmacion-b" data-r="0">${e(cancelar)}</button>` : ""}<button type="button" class="mj-dialogo-confirmacion-b ok" data-r="1">${e(ok)}</button></div>`;
    let hecho = false;
