(() => {
  const ICON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
  let pop, actual;
  const cerrar = () => { if (!actual) return; actual.btn.classList.remove("open"); pop.hidden = true; actual = null; };
  const elegir = (sel, i) => { if (sel.selectedIndex !== i) { sel.selectedIndex = i; sel.dispatchEvent(new Event("change", { bubbles: true })); } };
  const marcar = () => pop.querySelectorAll(".mj-desplegable-propio-opt").forEach(o => o.classList.toggle("foco", +o.dataset.i === actual.foco));
  function abrir(sel, btn) {
    if (actual?.sel === sel) return cerrar(); cerrar();
    pop ??= Object.assign(document.createElement("div"), { className: "mj-desplegable-propio-pop", hidden: true });
    (sel.closest("dialog") || document.body).appendChild(pop);
    pop.innerHTML = [...sel.options].map((o, i) => `<div class="mj-desplegable-propio-opt ${i === sel.selectedIndex ? "on" : ""}" data-i="${i}">${o.textContent}</div>`).join("");
    pop.hidden = false; actual = { sel, btn, foco: sel.selectedIndex }; btn.classList.add("open");
    const r = btn.getBoundingClientRect(); pop.style.minWidth = r.width + "px"; pop.style.maxHeight = "300px";
    const alto = Math.min(pop.scrollHeight, 300), abajo = innerHeight - r.bottom;
    pop.style.top = (abajo < alto + 12 && r.top > abajo ? r.top - alto - 6 : r.bottom + 6) + "px"; pop.style.left = r.left + "px";
  }
  document.querySelectorAll(".mj-desplegable-propio select").forEach(sel => {
    const btn = document.createElement("button"); btn.type = "button"; btn.className = "mj-desplegable-propio-sel";
    sel.classList.add("nativo"); sel.tabIndex = -1; sel.after(btn);
    const sync = () => btn.innerHTML = `<span>${sel.options[sel.selectedIndex]?.textContent || "&nbsp;"}</span>${ICON}`;
    sel.addEventListener("change", sync); sync();
    btn.onclick = e => { e.preventDefault(); abrir(sel, btn); };
    btn.onkeydown = e => { const ab = actual?.sel === sel, n = sel.options.length;
      if (e.key === "ArrowDown" || e.key === "ArrowUp") { e.preventDefault(); const i = Math.max(0, Math.min(n - 1, (ab ? actual.foco : sel.selectedIndex) + (e.key === "ArrowDown" ? 1 : -1))); if (ab) { actual.foco = i; marcar(); } else elegir(sel, i); }
      else if ((e.key === "Enter" || e.key === " ") && ab) { e.preventDefault(); elegir(sel, actual.foco); cerrar(); }
      else if (e.key === "Escape" || e.key === "Tab") cerrar(); };
  });
  document.addEventListener("mousedown", e => { if (!actual) return; const o = e.target.closest(".mj-desplegable-propio-opt");
    if (o) { e.preventDefault(); const { sel, btn } = actual; elegir(sel, +o.dataset.i); cerrar(); btn.focus(); return; }
    if (!e.target.closest(".mj-desplegable-propio-pop, .mj-desplegable-propio-sel")) cerrar(); });
  addEventListener("scroll", e => { if (actual && !e.target.closest?.(".mj-desplegable-propio-pop")) cerrar(); }, true);
  addEventListener("resize", cerrar);
})();

